function docsCode(r, lang) {
  const m = API_META[r.api];
  if (!m) return `<pre><code>curl "https://pixharvest.com/docs"</code></pre>`;
  const paid = r.slug && (r.slug.includes("changes") || r.slug.includes("intel") || r.slug.includes("landscape") || r.slug.includes("batch"));
  const hdr = paid ? `-H "Authorization: Bearer YOUR_KEY"` : "";
  const url = `https://${m.sub}/v1/${r.slug.includes("changes") ? "changes" : r.slug.includes("intel") ? "intel" : r.slug.includes("landscape") ? "landscape" : r.slug.includes("batch") ? "batch" : "snapshot"}`;
  if (lang === "python") return `<pre><code>import requests
r = requests.get("${url}", headers={"Authorization": "Bearer YOUR_KEY"})
data = r.json()
print(data)</code></pre>`;
  if (lang === "node") return `<pre><code>const res = await fetch("${url}", { headers: { Authorization: "Bearer YOUR_KEY" } });
const data = await res.json();
console.log(data);</code></pre>`;
  if (lang === "ruby") return `<pre><code>require "net/http"
uri = URI("${url}")
req = Net::HTTP::Get.new(uri)
req["Authorization"] = "Bearer YOUR_KEY"
puts Net::HTTP.start(uri.host, uri.port, use_ssl: true) { |h| h.request(req) }.body</code></pre>`;
  if (lang === "go") return `<pre><code>req, _ := http.NewRequest("GET", "${url}", nil)
req.Header.Set("Authorization", "Bearer YOUR_KEY")
resp, _ := http.DefaultClient.Do(req)
defer resp.Body.Close()
io.Copy(os.Stdout, resp.Body)</code></pre>`;
  if (lang === "rust") return `<pre><code>let resp = reqwest::Client::new()
  .get("${url}")
  .header("Authorization", "Bearer YOUR_KEY")
  .send().await?;
println!("{}", resp.text().await?);</code></pre>`;
  return `<pre><code>curl "${url}" ${hdr}</code></pre>`;
}
