  const linkRow = `<p><a href="/docs">\u2190 All docs</a> \xB7 <a href="/try">Live demo</a> \xB7 <a href="/pricing">Pricing</a> \xB7 <a href="/docs/auth">Auth &amp; payment</a></p>`;
